(function () {
  "use strict";

  /* ── Component factory ── */
  function DeleteConfirmDialog({ dialogEl, triggerEl, imageNameEl, onConfirm }) {
    const closeBtn = dialogEl.querySelector(".dialog__close");
    const cancelBtn = dialogEl.querySelector("[data-action='cancel']");
    const confirmBtn = dialogEl.querySelector("[data-action='confirm']");
    const liveRegion = document.getElementById("live-region");

    let previousFocus = null;

    /* Collect all focusable elements inside the dialog */
    function getFocusable() {
      return Array.from(
        dialogEl.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        )
      ).filter((el) => !el.disabled);
    }

    /* Trap Tab focus within the dialog */
    function handleKeydown(e) {
      if (e.key === "Escape") {
        // Native <dialog> handles Escape, but we animate the close ourselves
        e.preventDefault();
        close();
        return;
      }
      if (e.key !== "Tab") return;

      const focusable = getFocusable();
      if (!focusable.length) { e.preventDefault(); return; }

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (e.shiftKey) {
        if (document.activeElement === first) {
          e.preventDefault();
          last.focus();
        }
      } else {
        if (document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    }

    function open() {
      previousFocus = document.activeElement;
      updateImageInfo();
      dialogEl.showModal();
      // Move focus to the first interactive element (close button)
      const focusable = getFocusable();
      if (focusable.length) focusable[0].focus();
      dialogEl.addEventListener("keydown", handleKeydown);
    }

    function close() {
      dialogEl.classList.add("is-closing");
      const duration = prefersReducedMotion() ? 0 : 150;
      setTimeout(() => {
        dialogEl.classList.remove("is-closing");
        dialogEl.close();
        dialogEl.removeEventListener("keydown", handleKeydown);
        // Restore focus to the trigger
        if (previousFocus) previousFocus.focus();
      }, duration);
    }

    function confirm() {
      const name = imageNameEl ? imageNameEl.textContent : "the image";
      close();
      // Notify screen readers after dialog closes
      setTimeout(() => {
        announce(`"${name}" has been deleted from your library.`);
      }, 160);
      if (typeof onConfirm === "function") onConfirm(name);
    }

    function updateImageInfo() {
      // Sync thumbnail and filename in the dialog preview row
      const mainImg = document.querySelector(".image-card__img");
      const dialogThumb = dialogEl.querySelector(".dialog__thumb");
      const dialogImgName = dialogEl.querySelector(".dialog__image-name");

      if (mainImg && dialogThumb) {
        dialogThumb.src = mainImg.src;
        dialogThumb.alt = mainImg.alt;
      }
      if (imageNameEl && dialogImgName) {
        dialogImgName.textContent = imageNameEl.textContent;
      }
    }

