  function DeleteConfirmDialog({ dialogEl, triggerEl, imageNameEl, onConfirm }) {
    const closeBtn = dialogEl.querySelector(".dialog__close");
    const cancelBtn = dialogEl.querySelector("[data-action='cancel']");
    const confirmBtn = dialogEl.querySelector("[data-action='confirm']");
