  background: linear-gradient(135deg, var(--color-accent), #a46ef8);
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  aria-hidden: true;
}

.app-header__title {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-text);
}

/* ── Page ── */
.page {
  max-width: 900px;
  margin: 0 auto;
}

.page__heading {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.page__subheading {
  color: var(--color-text-muted);
  font-size: 0.9375rem;
  margin-bottom: 2rem;
}

/* ── Image preview card ── */
.image-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  max-width: 520px;
}

.image-card__preview {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: var(--color-surface-alt);
}

.image-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.image-card__body {
  padding: 1.25rem 1.5rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.image-card__meta {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.image-card__name {
  font-size: 1rem;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.image-card__details {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

.image-card__actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4em;
  padding: 0.5rem 1rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  text-decoration: none;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), box-shadow var(--transition);
}

.btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.btn--ghost {
  background: transparent;
  border-color: var(--color-border);
  color: var(--color-text-muted);
}
.btn--ghost:hover {
  background: var(--color-surface-alt);
  color: var(--color-text);
  border-color: #404666;
}

.btn--danger {
  background: var(--color-danger-bg);
  border-color: rgba(224, 82, 82, 0.35);
  color: var(--color-danger);
}
.btn--danger:hover {
  background: rgba(224, 82, 82, 0.22);
  border-color: rgba(224, 82, 82, 0.6);
  color: var(--color-danger-hover);
}
.btn--danger:focus-visible {
  outline-color: var(--color-danger);
}

.btn--primary-danger {
  background: var(--color-danger);
  border-color: var(--color-danger);
  color: #fff;
}
.btn--primary-danger:hover {
  background: var(--color-danger-hover);
  border-color: var(--color-danger-hover);
}
.btn--primary-danger:focus-visible {
  outline-color: var(--color-danger);
}

.btn--secondary {
  background: var(--color-surface-alt);
  border-color: var(--color-border);
  color: var(--color-text-muted);
}
.btn--secondary:hover {
  background: #2a2f45;
  color: var(--color-text);
  border-color: #404666;
}

.btn svg { flex-shrink: 0; }

/* ── Dialog backdrop / native <dialog> ── */
dialog {
  /* Reset browser defaults */
  border: none;
  padding: 0;
  background: transparent;
  color: inherit;
  max-width: 100%;
  max-height: 100%;

  /* Positioning: centered overlay */
  position: fixed;
  inset: 0;
  margin: auto;
  width: min(440px, calc(100vw - 2rem));

  /* Hidden by default — JS uses showModal() */
}

dialog::backdrop {
  background: var(--color-overlay);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
}

/* Animation */
@keyframes dialog-in {
  from { opacity: 0; transform: translateY(-12px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes dialog-out {
  from { opacity: 1; transform: translateY(0) scale(1); }
  to   { opacity: 0; transform: translateY(-12px) scale(0.97); }
}

dialog[open] { animation: dialog-in 180ms ease forwards; }
dialog.is-closing { animation: dialog-out 150ms ease forwards; }

/* ── Dialog inner layout ── */
.dialog {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-dialog);
  width: 100%;
  padding: 0;
  overflow: hidden;
}

.dialog__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.5rem 1.5rem 0;
}

.dialog__icon-wrap {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-danger-bg);
  border: 1px solid rgba(224, 82, 82, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--color-danger);
}

.dialog__close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-text-muted);
  cursor: pointer;
  font-family: inherit;
  flex-shrink: 0;
  transition: background var(--transition), color var(--transition);
}
.dialog__close:hover { background: var(--color-surface-alt); color: var(--color-text); }
.dialog__close:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.dialog__body {
  padding: 1rem 1.5rem 0;
}

.dialog__title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.dialog__description {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}

.dialog__image-preview {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 1rem;
  padding: 0.75rem;
  background: var(--color-surface-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
}

.dialog__thumb {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  flex-shrink: 0;
}

.dialog__image-name {
  font-size: 0.875rem;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dialog__image-size {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}

.dialog__footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  padding: 1.25rem 1.5rem 1.5rem;
}

/* ── Status region (live) ── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Forced colors ── */
@media (forced-colors: active) {
  .dialog {
    border: 2px solid ButtonBorder;
  }
  .btn--primary-danger {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonBorder;
  }
  .dialog__icon-wrap {
    background: Canvas;
    border-color: ButtonBorder;
    color: ButtonText;
  }
  dialog::backdrop {
    background: rgba(0,0,0,0.5);
  }
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  dialog[open], dialog.is-closing { animation: none; }
